def resolve(path, cwd, links):
    """
    Resolve a path to its canonical absolute form, following symlinks.

    Args:
        path: The path to resolve (absolute or relative to cwd)
        cwd: Current working directory (canonical absolute path)
        links: Dict mapping canonical absolute paths to symlink targets

    Returns:
        The canonical absolute path, or None if there's an error
    """
    # Count symlinks followed to detect cycles
    link_count = [0]  # Use list to allow modification in nested function

    def resolve_helper(p, current_dir):
        """Helper function to recursively resolve a path."""
        if link_count[0] > 8:
            return None

        # Split path into components
        if p.startswith('/'):
            # Absolute path
            current = ''
        else:
            # Relative path - start from current_dir
            current = current_dir
            p = p.lstrip('/')

        # Split by '/' and process each component
        components = p.split('/')

        for component in components:
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                if current == '':
                    current = '/'
                else:
                    # Move to parent
                    last_slash = current.rfind('/')
                    if last_slash == 0:
                        current = '/'
                    else:
                        current = current[:last_slash]
                continue

            # Append component to current path
            if current == '/':
                new_path = '/' + component
            else:
                new_path = current + '/' + component

            # Check if this path is a symlink
            if new_path in links:
                link_count[0] += 1
                if link_count[0] > 8:
                    return None

                target = links[new_path]

                # Determine the directory containing the symlink
                if new_path == '/':
                    link_dir = '/'
                else:
                    last_slash = new_path.rfind('/')
                    if last_slash == 0:
                        link_dir = '/'
                    else:
                        link_dir = new_path[:last_slash]

                # Resolve the target relative to link_dir
                if target.startswith('/'):
                    # Absolute target
                    resolved_target = resolve_helper(target, '/')
                else:
                    # Relative target
                    resolved_target = resolve_helper(target, link_dir)

                if resolved_target is None:
                    return None

                current = resolved_target
            else:
                current = new_path

        # Ensure we return '/' for root, not empty string
        if current == '':
            current = '/'

        return current

    # Start resolution
    if path.startswith('/'):
        result = resolve_helper(path, '/')
    else:
        result = resolve_helper(path, cwd)

    return result

